\begin{aligned}
\mathsf{Ax}^{FM}_{\forall,2}
=\;&\{(\forall_Ox(A\to B))\to(A\to\forall_OxB):
x\in\mathsf{OVar},\ A,B\in\mathsf{Frm}_{FM},\ x\notin\operatorname{OFV}_{F}(A)\}\\
\cup{}&\{(\forall_Gg(A\to B))\to(A\to\forall_GgB):
