\begin{aligned}
\mathsf{Ax}^{FM}_{=,2}
=\;&\{(t\doteq u)\to(A[x:=t]_O\to A[x:=u]_O):
x\in\mathsf{OVar},\ t,u\in\mathsf{OTerm}_{FM},\ A\in\mathsf{Frm}_{FM}\}\\
\cup{}&\{(\gamma\doteq_G\delta)\to(A[g:=\gamma]_G\to A[g:=\delta]_G):
